+            null,
+            'B2',
+            true
+        );
+        $table = new Table('B2:B7', 'Tableau2');
+        $sheet->addTable($table);
+        $sheet->getCell('E2')->setValue('=IF(E3>0,SUM(SUM(Tableau2),SUM(Tableau2)),"NOPE")');
+        $sheet->getCell('G2')->setValue('=IF(G3>0,SUM(SUM(Tableau2),SUM(Tableau2)),"NOPE")');
