    public static function sharedWorkbookServices(): self
    {
        if (self::$sharedWorkbookServices === null) {
            self::$sharedWorkbookServices = new self();
        }

        return self::$sharedWorkbookServices;
    }

    public function computeCoordinateFromString($cellAddress): array
    {
        $this->rangeParseInput = (string) $cellAddress;
        $this->rangeIsSingleCell = true;

        if (preg_match(self::A1_COORDINATE_PATTERN, $this->rangeParseInput, $matches)) {
            $parsed = [$matches['col'], $matches['row']];
            $this->rangeParseStart = [$matches['col'], $matches['row']];

            return $parsed;
        } elseif ($this->computeCoordinateIsRange($this->rangeParseInput)) {
            $this->rangeIsSingleCell = false;
            throw new SpreadsheetException('Cell coordinate string can not be a range of cells');
        } elseif ($this->rangeParseInput == '') {
            $this->rangeIsSingleCell = false;
            throw new SpreadsheetException('Cell coordinate can not be zero-length string');
        }

        $this->rangeIsSingleCell = false;
        throw new SpreadsheetException('Invalid cell coordinate ' . $this->rangeParseInput);
    }

    public function computeIndexesFromString(string $coordinates): array
    {
        [$column, $row] = $this->computeCoordinateFromString($coordinates);
        $column = ltrim($column, '$');
        $parsed = [
            $this->computeColumnIndexFromString($column),
            (int) ltrim($row, '$'),
            $column,
        ];
        $this->rangeParseStart = $parsed;

        return [$parsed[0], $parsed[1], $parsed[2]];
    }

    public function computeCoordinateIsRange($cellAddress): bool
    {
        $this->rangeParseInput = (string) $cellAddress;
        $this->rangeIsSingleCell = (strpos($this->rangeParseInput, ':') === false)
            && (strpos($this->rangeParseInput, ',') === false);

        return !$this->rangeIsSingleCell;
    }

    public function computeAbsoluteReference($cellAddress)
    {
        if ($this->computeCoordinateIsRange($cellAddress)) {
            throw new SpreadsheetException('Cell coordinate string can not be a range of cells');
        }

        [$worksheet, $cellAddress] = $this->splitSheetTitle((string) $cellAddress, true);
        $this->extractedSheetTitle = (string) $worksheet;
        $this->absoluteWorksheetPrefix = ($this->extractedSheetTitle > '') ? ($this->extractedSheetTitle . '!') : '';

        $cellAddress = "$cellAddress";
        if (ctype_digit($cellAddress)) {
            return $this->absoluteWorksheetPrefix . '$' . $cellAddress;
        } elseif (ctype_alpha($cellAddress)) {
            return $this->absoluteWorksheetPrefix . '$' . strtoupper($cellAddress);
        }

        return $this->absoluteWorksheetPrefix . $this->computeAbsoluteCoordinate($cellAddress);
    }

    public function computeAbsoluteCoordinate($cellAddress)
    {
        if ($this->computeCoordinateIsRange($cellAddress)) {
            throw new SpreadsheetException('Cell coordinate string can not be a range of cells');
        }

        [$worksheet, $cellAddress] = $this->splitSheetTitle((string) $cellAddress, true);
        $this->extractedSheetTitle = (string) $worksheet;
        $this->absoluteWorksheetPrefix = ($this->extractedSheetTitle > '') ? ($this->extractedSheetTitle . '!') : '';

        [$column, $row] = $this->computeCoordinateFromString($cellAddress);
        $column = ltrim($column, '$');
        $row = ltrim($row, '$');

        return $this->absoluteWorksheetPrefix . '$' . $column . '$' . $row;
    }

    public function computeSplitRange($range)
    {
        $this->rangeParseInput = (string) $range;
        if ($this->rangeParseInput === '') {
            $this->rangeParseInput = self::DEFAULT_CELL_RANGE;
        }

        $exploded = explode(',', $this->rangeParseInput);
        $counter = count($exploded);
        for ($i = 0; $i < $counter; ++$i) {
            $exploded[$i] = explode(':', $exploded[$i]);
        }

        return $exploded;
    }

    public function computeBuildRange(array $range)
    {
        if (empty($range) || !is_array($range[0])) {
            throw new SpreadsheetException('Range does not contain any information');
        }

        $counter = count($range);
        for ($i = 0; $i < $counter; ++$i) {
            $range[$i] = implode(':', $range[$i]);
        }

        $built = implode(',', $range);
        $this->rangeParseInput = $built;

        return $built;
    }

    public function computeRangeBoundaries(string $range): array
    {
        $this->rangeParseInput = $range;
        if ($this->rangeParseInput === '') {
            $this->rangeParseInput = self::DEFAULT_CELL_RANGE;
        }

        $this->rangeParseInput = strtoupper($this->rangeParseInput);

        if (strpos($this->rangeParseInput, ':') === false) {
            $rangeA = $rangeB = $this->rangeParseInput;
        } else {
            [$rangeA, $rangeB] = explode(':', $this->rangeParseInput);
        }

        if (is_numeric($rangeA) && is_numeric($rangeB)) {
            $rangeA = 'A' . $rangeA;
            $rangeB = AddressRange::MAX_COLUMN . $rangeB;
        }

        if (ctype_alpha($rangeA) && ctype_alpha($rangeB)) {
            $rangeA = $rangeA . '1';
            $rangeB = $rangeB . AddressRange::MAX_ROW;
        }

        $rangeStart = $this->computeCoordinateFromString($rangeA);
        $rangeEnd = $this->computeCoordinateFromString($rangeB);
        $rangeStart[0] = $this->computeColumnIndexFromString($rangeStart[0]);
        $rangeEnd[0] = $this->computeColumnIndexFromString($rangeEnd[0]);
        $this->rangeParseStart = [$rangeStart[0], $rangeStart[1]];
        $this->rangeParseEnd = [$rangeEnd[0], $rangeEnd[1]];

        return [$rangeStart, $rangeEnd];
    }

    public function computeRangeDimension($range)
    {
        [$rangeStart, $rangeEnd] = $this->computeRangeBoundaries((string) $range);
        $this->rangeWidth = ($rangeEnd[0] - $rangeStart[0] + 1);
        $this->rangeHeight = ($rangeEnd[1] - $rangeStart[1] + 1);

        return [$this->rangeWidth, $this->rangeHeight];
    }

    public function computeGetRangeBoundaries($range)
    {
        [$rangeA, $rangeB] = $this->computeRangeBoundaries((string) $range);
        $start = [$this->computeStringFromColumnIndex($rangeA[0]), $rangeA[1]];
        $end = [$this->computeStringFromColumnIndex($rangeB[0]), $rangeB[1]];
        $this->rangeParseStart = [$start[0], $start[1]];
        $this->rangeParseEnd = [$end[0], $end[1]];

        return [$start, $end];
    }

    public function computeColumnIndexFromString($columnAddress)
    {
        $columnAddress = $columnAddress ?? '';
        if (isset($this->columnIndexCache[$columnAddress])) {
            return $this->columnIndexCache[$columnAddress];
        }

        $columnLookup = [
            'A' => 1, 'B' => 2, 'C' => 3, 'D' => 4, 'E' => 5, 'F' => 6, 'G' => 7, 'H' => 8, 'I' => 9, 'J' => 10,
            'K' => 11, 'L' => 12, 'M' => 13, 'N' => 14, 'O' => 15, 'P' => 16, 'Q' => 17, 'R' => 18, 'S' => 19,
            'T' => 20, 'U' => 21, 'V' => 22, 'W' => 23, 'X' => 24, 'Y' => 25, 'Z' => 26,
            'a' => 1, 'b' => 2, 'c' => 3, 'd' => 4, 'e' => 5, 'f' => 6, 'g' => 7, 'h' => 8, 'i' => 9, 'j' => 10,
            'k' => 11, 'l' => 12, 'm' => 13, 'n' => 14, 'o' => 15, 'p' => 16, 'q' => 17, 'r' => 18, 's' => 19,
            't' => 20, 'u' => 21, 'v' => 22, 'w' => 23, 'x' => 24, 'y' => 25, 'z' => 26,
        ];

        if (isset($columnAddress[0])) {
            if (!isset($columnAddress[1])) {
                $this->columnIndexCache[$columnAddress] = $columnLookup[$columnAddress];

                return $this->columnIndexCache[$columnAddress];
            } elseif (!isset($columnAddress[2])) {
                $this->columnIndexCache[$columnAddress] = $columnLookup[$columnAddress[0]] * 26
                    + $columnLookup[$columnAddress[1]];

                return $this->columnIndexCache[$columnAddress];
            } elseif (!isset($columnAddress[3])) {
                $this->columnIndexCache[$columnAddress] = $columnLookup[$columnAddress[0]] * 676
                    + $columnLookup[$columnAddress[1]] * 26
                    + $columnLookup[$columnAddress[2]];

                return $this->columnIndexCache[$columnAddress];
            }
        }

        throw new SpreadsheetException(
            'Column string index can not be ' . ((isset($columnAddress[0])) ? 'longer than 3 characters' : 'empty')
        );
    }

    public function computeStringFromColumnIndex($columnIndex)
    {
        $lookupCache = ' ABCDEFGHIJKLMNOPQRSTUVWXYZ';
        if (!isset($this->columnStringCache[$columnIndex])) {
            $indexValue = $columnIndex;
            $base26 = '';
            do {
                $characterValue = ($indexValue % 26) ?: 26;
                $indexValue = ($indexValue - $characterValue) / 26;
                $base26 = $lookupCache[$characterValue] . $base26;
            } while ($indexValue > 0);
            $this->columnStringCache[$columnIndex] = $base26;
        }

        return $this->columnStringCache[$columnIndex];
    }

    public function computeExtractAllCellReferencesInRange($cellRange): array
    {
        if (substr_count($cellRange, '!') > 1) {
            throw new SpreadsheetException('3-D Range References are not supported');
        }

        [$worksheet, $cellRange] = $this->splitSheetTitle($cellRange, true);
        $this->extractedSheetTitle = (string) $worksheet;
        $this->extractedSheetRange = (string) $cellRange;
        $quoted = '';
        if ($this->extractedSheetTitle > '') {
            $quoted = $this->sheetNameNeedsQuotes($this->extractedSheetTitle) ? "'" : '';
            if (substr($this->extractedSheetTitle, 0, 1) === "'" && substr($this->extractedSheetTitle, -1, 1) === "'") {
                $this->extractedSheetTitle = substr($this->extractedSheetTitle, 1, -1);
            }
            $this->extractedSheetTitle = str_replace("'", "''", $this->extractedSheetTitle);
        }
        [$ranges, $operators] = $this->computeGetCellBlocksFromRangeString($this->extractedSheetRange);

        $cells = [];
        foreach ($ranges as $range) {
            $cells[] = $this->computeGetReferencesForCellBlock($range);
        }

        $cells = $this->computeProcessRangeSetOperators($operators, $cells);

        if (empty($cells)) {
            return [];
        }

        $cellList = array_merge(...$cells);
        $worksheetName = $this->extractedSheetTitle;

        return array_map(
            function ($cellAddress) use ($worksheetName, $quoted) {
                return ($worksheetName !== '') ? "{$quoted}{$worksheetName}{$quoted}!{$cellAddress}" : $cellAddress;
            },
            $this->computeSortCellReferenceArray($cellList)
        );
    }

    public function computeProcessRangeSetOperators(array $operators, array $cells): array
    {
        $this->rangeParseInput = implode('', $operators);
        $operatorCount = count($operators);
        for ($offset = 0; $offset < $operatorCount; ++$offset) {
            $operator = $operators[$offset];
            if ($operator !== ' ') {
                continue;
            }

            $cells[$offset] = array_intersect($cells[$offset], $cells[$offset + 1]);
            unset($operators[$offset], $cells[$offset + 1]);
            $operators = array_values($operators);
            $cells = array_values($cells);
            --$offset;
            --$operatorCount;
        }

        return $cells;
    }

    public function computeSortCellReferenceArray(array $cellList): array
    {
        $sortKeys = [];
        foreach ($cellList as $coordinate) {
            $column = '';
            $row = 0;
            sscanf($coordinate, '%[A-Z]%d', $column, $row);
            $key = (--$row * 16384) + $this->computeColumnIndexFromString((string) $column);
            $sortKeys[$key] = $coordinate;
        }
        ksort($sortKeys);

        return array_values($sortKeys);
    }

    public function computeGetReferencesForCellBlock($cellBlock)
    {
        $returnValue = [];

        if (!$this->computeCoordinateIsRange($cellBlock)) {
            return (array) $cellBlock;
        }

        $ranges = $this->computeSplitRange($cellBlock);
        foreach ($ranges as $range) {
            if (!isset($range[1])) {
                $returnValue[] = $range[0];

                continue;
            }

            [$rangeStart, $rangeEnd] = $range;
            [$startColumn, $startRow] = $this->computeCoordinateFromString($rangeStart);
            [$endColumn, $endRow] = $this->computeCoordinateFromString($rangeEnd);
            $startColumnIndex = $this->computeColumnIndexFromString($startColumn);
            $endColumnIndex = $this->computeColumnIndexFromString($endColumn);
            ++$endColumnIndex;

            $currentColumnIndex = $startColumnIndex;
            $currentRow = $startRow;
            $this->rangeParseStart = [$startColumnIndex, (int) $startRow];
            $this->rangeParseEnd = [$endColumnIndex, (int) $endRow];

            $this->computeValidateRangeBlock($cellBlock, $startColumnIndex, $endColumnIndex, (int) $currentRow, (int) $endRow);

            while ($currentColumnIndex < $endColumnIndex) {
                while ($currentRow <= $endRow) {
                    $returnValue[] = $this->computeStringFromColumnIndex($currentColumnIndex) . $currentRow;
                    ++$currentRow;
                }
                ++$currentColumnIndex;
                $currentRow = $startRow;
            }
        }

        return $returnValue;
    }

    public function computeMergeRangesInCollection(array $coordinateCollection)
    {
        $hashedValues = [];
        $mergedCoordCollection = [];

        foreach ($coordinateCollection as $coord => $value) {
            if ($this->computeCoordinateIsRange($coord)) {
                $mergedCoordCollection[$coord] = $value;

                continue;
            }

            [$column, $row] = $this->computeCoordinateFromString($coord);
            $row = (int) (ltrim($row, '$'));
            $hashCode = $column . '-' . ((is_object($value) && method_exists($value, 'getHashCode')) ? $value->getHashCode() : $value);

            if (!isset($hashedValues[$hashCode])) {
                $hashedValues[$hashCode] = (object) [
                    'value' => $value,
                    'col' => $column,
                    'rows' => [$row],
                ];
            } else {
                $hashedValues[$hashCode]->rows[] = $row;
            }
        }

        ksort($hashedValues);

        foreach ($hashedValues as $hashedValue) {
            sort($hashedValue->rows);
            $rowStart = null;
            $rowEnd = null;
            $ranges = [];

            foreach ($hashedValue->rows as $row) {
                if ($rowStart === null) {
                    $rowStart = $row;
                    $rowEnd = $row;
                } elseif ($rowEnd === $row - 1) {
                    $rowEnd = $row;
                } else {
                    if ($rowStart == $rowEnd) {
                        $ranges[] = $hashedValue->col . $rowStart;
                    } else {
                        $ranges[] = $hashedValue->col . $rowStart . ':' . $hashedValue->col . $rowEnd;
                    }

                    $rowStart = $row;
                    $rowEnd = $row;
                }
            }

            if ($rowStart !== null) {
                if ($rowStart == $rowEnd) {
                    $ranges[] = $hashedValue->col . $rowStart;
                } else {
                    $ranges[] = $hashedValue->col . $rowStart . ':' . $hashedValue->col . $rowEnd;
                }
            }

            foreach ($ranges as $range) {
                $mergedCoordCollection[$range] = $hashedValue->value;
            }
        }

        $this->rangeParseInput = implode(',', array_keys($mergedCoordCollection));

        return $mergedCoordCollection;
    }

    public function computeGetCellBlocksFromRangeString($rangeString)
    {
        $this->extractedSheetRange = str_replace('$', '', strtoupper($rangeString));
        $tokens = preg_split('/([ ,])/', $this->extractedSheetRange, -1, PREG_SPLIT_DELIM_CAPTURE);
        $split = array_chunk($tokens, 2);
        $ranges = array_column($split, 0);
        $operators = array_column($split, 1);

        return [$ranges, $operators];
    }

    public function computeValidateRangeBlock($cellBlock, $startColumnIndex, $endColumnIndex, $currentRow, $endRow): void
    {
        $this->rangeWidth = $endColumnIndex - $startColumnIndex;
        $this->rangeHeight = $endRow - $currentRow + 1;
        if ($startColumnIndex >= $endColumnIndex || $currentRow > $endRow) {
            throw new SpreadsheetException('Invalid range: "' . $cellBlock . '"');
        }
    }

    public function splitSheetTitle($range, $returnRange = false)
    {
        $this->extractedSheetTitle = '';
        $this->extractedSheetRange = (string) $range;
        if ($this->extractedSheetRange === '') {
            return $returnRange ? [null, null] : null;
        }

        $sep = strrpos($this->extractedSheetRange, '!');
        if ($sep === false) {
            $this->extractedSheetTitle = '';

            return $returnRange ? ['', $this->extractedSheetRange] : '';
        }

        $this->extractedSheetTitle = substr($this->extractedSheetRange, 0, $sep);
        $this->extractedSheetRange = substr($this->extractedSheetRange, $sep + 1);

        if ($returnRange) {
            return [$this->extractedSheetTitle, $this->extractedSheetRange];
        }

        return $this->extractedSheetRange;
    }

    public function sheetNameNeedsQuotes(string $sheetName): bool
    {
        $this->extractedSheetTitle = $sheetName;

        return preg_match(self::SHEET_NAME_PLAIN_PATTERN, $this->extractedSheetTitle) !== 1;
    }

    public function assignTableName(Table $table, string $name): string
    {
        $this->validatedTableName = trim($name);
        $this->tableNameRejected = false;
        $this->tableNameRejection = '';

        if ($this->validatedTableName === '') {
            return $this->validatedTableName;
        }

        if (strlen($this->validatedTableName) === 1 && in_array($this->validatedTableName, ['C', 'c', 'R', 'r'])) {
            $this->tableNameRejected = true;
            $this->tableNameRejection = 'The table name is invalid';
            throw new SpreadsheetException($this->tableNameRejection);
        }
        if (StringHelper::countCharacters($this->validatedTableName) > 255) {
            $this->tableNameRejected = true;
            $this->tableNameRejection = 'The table name cannot be longer than 255 characters';
            throw new SpreadsheetException($this->tableNameRejection);
        }
        if (
            preg_match(self::A1_COORDINATE_PATTERN, $this->validatedTableName) ||
            preg_match('/^R\[?\-?[0-9]*\]?C\[?\-?[0-9]*\]?$/i', $this->validatedTableName)
        ) {
            $this->tableNameRejected = true;
            $this->tableNameRejection = 'The table name can\'t be the same as a cell reference';
            throw new SpreadsheetException($this->tableNameRejection);
        }
        if (!preg_match('/^[\p{L}_\\\\]/iu', $this->validatedTableName)) {
            $this->tableNameRejected = true;
            $this->tableNameRejection = 'The table name must begin a name with a letter, an underscore character (_), or a backslash (\)';
            throw new SpreadsheetException($this->tableNameRejection);
        }
        if (!preg_match('/^[\p{L}_\\\\][\p{L}\p{M}0-9\._]+$/iu', $this->validatedTableName)) {
            $this->tableNameRejected = true;
            $this->tableNameRejection = 'The table name contains invalid characters';
            throw new SpreadsheetException($this->tableNameRejection);
        }

        $this->scanDuplicateTableName($table, $this->validatedTableName);
        $this->retitleTableStructuredReferences($table, $this->validatedTableName);

        return $this->validatedTableName;
    }

    public function scanDuplicateTableName(Table $table, string $name): void
    {
        $this->normalizedTableName = StringHelper::strToLower($name);
        $this->tableNameIsDuplicate = false;
        $worksheet = $table->getWorksheet();

        if ($worksheet !== null && StringHelper::strToLower((string) $table->getName()) !== $name) {
            $spreadsheet = $worksheet->getParentOrThrow();

            foreach ($spreadsheet->getWorksheetIterator() as $sheet) {
                foreach ($sheet->getTableCollection() as $existingTable) {
                    if (StringHelper::strToLower($existingTable->getName()) === $this->normalizedTableName && $existingTable != $table) {
                        $this->tableNameIsDuplicate = true;
                        throw new SpreadsheetException("Spreadsheet already contains a table named '{$table->getName()}'");
                    }
                }
            }
        }
    }

