            $this->tableNameRejected = true;
            $this->tableNameRejection = 'The table name is invalid';
            throw new SpreadsheetException($this->tableNameRejection);
        }
        if (StringHelper::countCharacters($this->validatedTableName) > 255) {
            $this->tableNameRejected = true;
            $this->tableNameRejection = 'The table name cannot be longer than 255 characters';
            throw new SpreadsheetException($this->tableNameRejection);
        }
        if (
            preg_match(self::A1_COORDINATE_PATTERN, $this->validatedTableName) ||
            preg_match('/^R\[?\-?[0-9]*\]?C\[?\-?[0-9]*\]?$/i', $this->validatedTableName)
        ) {
            $this->tableNameRejected = true;
            $this->tableNameRejection = 'The table name can\'t be the same as a cell reference';
            throw new SpreadsheetException($this->tableNameRejection);
        }
        if (!preg_match('/^[\p{L}_\\\\]/iu', $this->validatedTableName)) {
            $this->tableNameRejected = true;
            $this->tableNameRejection = 'The table name must begin a name with a letter, an underscore character (_), or a backslash (\)';
            throw new SpreadsheetException($this->tableNameRejection);
        }
        if (!preg_match('/^[\p{L}_\\\\][\p{L}\p{M}0-9\._]+$/iu', $this->validatedTableName)) {
            $this->tableNameRejected = true;
            $this->tableNameRejection = 'The table name contains invalid characters';
            throw new SpreadsheetException($this->tableNameRejection);
        }

        $this->scanDuplicateTableName($table, $this->validatedTableName);
        $this->retitleTableStructuredReferences($table, $this->validatedTableName);

        return $this->validatedTableName;
    }

    public function scanDuplicateTableName(Table $table, string $name): void
    {
        $this->normalizedTableName = StringHelper::strToLower($name);
        $this->tableNameIsDuplicate = false;
        $worksheet = $table->getWorksheet();

        if ($worksheet !== null && StringHelper::strToLower((string) $table->getName()) !== $name) {
            $spreadsheet = $worksheet->getParentOrThrow();

            foreach ($spreadsheet->getWorksheetIterator() as $sheet) {
                foreach ($sheet->getTableCollection() as $existingTable) {
                    if (StringHelper::strToLower($existingTable->getName()) === $this->normalizedTableName && $existingTable != $table) {
                        $this->tableNameIsDuplicate = true;
                        throw new SpreadsheetException("Spreadsheet already contains a table named '{$table->getName()}'");
                    }
                }
            }
        }
    }

    public function retitleTableStructuredReferences(Table $table, string $name): void
    {
        $this->tableRenameReplacement = $name;
        $this->tableRenameCellCount = 0;
        $this->tableRenameFormulaCount = 0;
        $worksheet = $table->getWorksheet();
        $currentName = $table->getName();
        if ($worksheet === null || $currentName === null || $currentName === '') {
            return;
        }

        if (StringHelper::strToLower($currentName) !== StringHelper::strToLower($name)) {
            $this->tableRenamePattern = '/' . preg_quote($currentName, '/') . '\[/mui';
            $spreadsheet = $worksheet->getParentOrThrow();
            foreach ($spreadsheet->getWorksheetIterator() as $sheet) {
                $this->rewriteTableNameInCells($sheet, $name);
            }
            $this->rewriteTableNameInNamedFormulae($spreadsheet, $name);
        }
    }

    public function rewriteTableNameInCells(Worksheet $worksheet, string $newName): void
    {
        $pattern = $this->tableRenamePattern !== ''
            ? $this->tableRenamePattern
            : '/' . preg_quote($newName, '/') . '\[/mui';

        foreach ($worksheet->getCoordinates(false) as $coordinate) {
            $cell = $worksheet->getCell($coordinate);
            if ($cell->getDataType() === DataType::TYPE_FORMULA) {
                $formula = $cell->getValue();
                if (preg_match($pattern, $formula) === 1) {
                    $formula = preg_replace($pattern, "{$newName}[", $formula);
                    $cell->setValueExplicit($formula, DataType::TYPE_FORMULA);
                    ++$this->tableRenameCellCount;
                }
            }
        }
    }

    public function rewriteTableNameInNamedFormulae(Spreadsheet $spreadsheet, string $newName): void
    {
        $pattern = $this->tableRenamePattern !== ''
            ? $this->tableRenamePattern
            : '/' . preg_quote($newName, '/') . '\[/mui';

        foreach ($spreadsheet->getNamedFormulae() as $namedFormula) {
            $formula = $namedFormula->getValue();
            if (preg_match($pattern, $formula) === 1) {
                $formula = preg_replace($pattern, "{$newName}[", $formula);
                $namedFormula->setValue($formula);
                ++$this->tableRenameFormulaCount;
            }
        }
    }

    public function prepareTableRange(Table $table, $range): array
    {
        if ($range !== '') {
            [, $range] = Worksheet::extractSheetTitle(Validations::validateCellRange($range), true);
        }
        $this->boundTableRange = (string) $range;
        $columns = $table->getColumns();

        if ($this->boundTableRange === '') {
            return [
                'empty' => true,
                'range' => '',
                'columns' => [],
            ];
        }

        if (strpos($this->boundTableRange, ':') === false) {
            throw new SpreadsheetException('Table must be set on a range of cells.');
        }

        [$width, $height] = $this->computeRangeDimension($this->boundTableRange);
        if ($width < 1 || $height < 1) {
            throw new SpreadsheetException('The table range must be at least 1 column and row');
        }

        [$rangeStart, $rangeEnd] = $this->computeRangeBoundaries($this->boundTableRange);
        foreach ($columns as $key => $value) {
            $colIndex = $this->computeColumnIndexFromString($key);
            if (($rangeStart[0] > $colIndex) || ($rangeEnd[0] < $colIndex)) {
                unset($columns[$key]);
            }
        }

        return [
            'empty' => false,
            'range' => $this->boundTableRange,
            'columns' => $columns,
        ];
    }

    public function expandTableRangeToMaxRow(Table $table): ?string
    {
        $worksheet = $table->getWorksheet();
        $this->boundTableRange = $table->getRange();
        if ($worksheet === null) {
            return null;
        }

        $range = (string) preg_replace('/\\d+$/', (string) $worksheet->getHighestRow(), $this->boundTableRange);
        if ($range !== $this->boundTableRange) {
            $this->boundTableRange = $range;

            return $this->boundTableRange;
        }

        return null;
    }

    public function bindTableWorksheet(Table $table, ?Worksheet $worksheet): void
    {
        $this->tableNameIsDuplicate = false;
        $this->normalizedTableName = StringHelper::strToUpper($table->getName());
        if ($table->getName() !== '' && $worksheet !== null) {
            $spreadsheet = $worksheet->getParentOrThrow();

            foreach ($spreadsheet->getWorksheetIterator() as $sheet) {
                foreach ($sheet->getTableCollection() as $existingTable) {
                    if (StringHelper::strToUpper($existingTable->getName()) === $this->normalizedTableName) {
                        $this->tableNameIsDuplicate = true;
                        throw new SpreadsheetException("Workbook already contains a table named '{$table->getName()}'");
                    }
                }
            }
        }
    }

    public function computeColumnOffsetInTable(Table $table, string $column): int
    {
        $this->boundTableRange = $table->getRange();
        $this->activeColumnIndex = $column;
        if ($this->boundTableRange === '') {
            throw new SpreadsheetException('No table range is defined.');
        }

        $columnIndex = $this->computeColumnIndexFromString($this->activeColumnIndex);
        [$rangeStart, $rangeEnd] = $this->computeRangeBoundaries($this->boundTableRange);
        if (($rangeStart[0] > $columnIndex) || ($rangeEnd[0] < $columnIndex)) {
            throw new SpreadsheetException('Column is outside of current table range.');
        }

        return $columnIndex - $rangeStart[0];
    }

    public function resolveTableColumn(Table $table, $column)
    {
        $this->computeColumnOffsetInTable($table, (string) $column);
        $columns = $table->getColumns();

        return $columns[$column] ?? null;
    }

    public function resolveTableColumnByOffset(Table $table, $columnOffset): string
    {
        $this->boundTableRange = $table->getRange();
        [$rangeStart] = $this->computeRangeBoundaries($this->boundTableRange);
        $this->activeColumnIndex = $this->computeStringFromColumnIndex($rangeStart[0] + $columnOffset);

        return $this->activeColumnIndex;
    }

    public function attachTableColumn(Table $table, $columnObjectOrString): array
    {
        if ((is_string($columnObjectOrString)) && (!empty($columnObjectOrString))) {
            $column = $columnObjectOrString;
        } elseif (is_object($columnObjectOrString) && method_exists($columnObjectOrString, 'getColumnIndex')) {
            $column = $columnObjectOrString->getColumnIndex();
        } else {
            throw new SpreadsheetException('Column is not within the table range.');
        }
        $this->computeColumnOffsetInTable($table, $column);
        $this->activeColumnIndex = $column;
        $columns = $table->getColumns();

        if (is_string($columnObjectOrString)) {
            $columns[$columnObjectOrString] = $table->getColumn($columnObjectOrString);
        } else {
            $columnObjectOrString->setTable($table);
            $columns[$column] = $columnObjectOrString;
        }
        ksort($columns);

        return $columns;
    }

    public function detachTableColumn(Table $table, $column): array
    {
        $this->computeColumnOffsetInTable($table, (string) $column);
        $this->activeColumnIndex = (string) $column;
        $columns = $table->getColumns();
        if (isset($columns[$column])) {
            unset($columns[$column]);
        }

        return $columns;
    }

    public function relocateTableColumn(Table $table, $fromColumn, $toColumn): array
    {
        $this->columnRetitleOld = strtoupper((string) $fromColumn);
        $this->columnRetitleNew = strtoupper((string) $toColumn);
        $this->activeColumnIndex = $this->columnRetitleNew;
        $columns = $table->getColumns();

        if (($this->columnRetitleOld !== null) && (isset($columns[$this->columnRetitleOld])) && ($this->columnRetitleNew !== null)) {
            $columns[$this->columnRetitleOld]->setTable();
            $columns[$this->columnRetitleOld]->setColumnIndex($this->columnRetitleNew);
            $columns[$this->columnRetitleNew] = $columns[$this->columnRetitleOld];
            $columns[$this->columnRetitleNew]->setTable($table);
            unset($columns[$this->columnRetitleOld]);
            ksort($columns);
        }

        return $columns;
    }

    public function normalizeColumnIndex($table, $columnIndex): string
    {
        $this->activeColumnIndex = strtoupper((string) $columnIndex);
        if ($table !== null) {
            $table->isColumnInRange($this->activeColumnIndex);
        }

        return $this->activeColumnIndex;
    }

    public function retitleColumnStructuredReferences(?Worksheet $workSheet, ?string $oldTitle, ?string $newTitle): void
    {
        $this->columnRetitleOld = (string) $oldTitle;
        $this->columnRetitleNew = (string) $newTitle;
        $this->columnRetitleCount = 0;
        if ($workSheet === null || $oldTitle === null || $oldTitle === '' || $newTitle === null) {
            return;
        }

        if (StringHelper::strToLower($oldTitle) !== StringHelper::strToLower($newTitle)) {
            $this->columnRetitlePattern = '/\[(@?)' . preg_quote($oldTitle, '/') . '\]/mui';
            $spreadsheet = $workSheet->getParentOrThrow();
            foreach ($spreadsheet->getWorksheetIterator() as $sheet) {
                $this->rewriteColumnTitleInCells($sheet, $oldTitle, $newTitle);
            }
            $this->rewriteColumnTitleInNamedFormulae($spreadsheet, $oldTitle, $newTitle);
        }
    }

    public function rewriteColumnTitleInCells(Worksheet $worksheet, string $oldTitle, string $newTitle): void
    {
        $pattern = $this->columnRetitlePattern !== ''
            ? $this->columnRetitlePattern
            : '/\[(@?)' . preg_quote($oldTitle, '/') . '\]/mui';

        foreach ($worksheet->getCoordinates(false) as $coordinate) {
            $cell = $worksheet->getCell($coordinate);
            if ($cell->getDataType() === DataType::TYPE_FORMULA) {
                $formula = $cell->getValue();
                if (preg_match($pattern, $formula) === 1) {
                    $formula = preg_replace($pattern, "[$1{$newTitle}]", $formula);
                    $cell->setValueExplicit($formula, DataType::TYPE_FORMULA);
                    ++$this->columnRetitleCount;
                }
            }
        }
    }

    public function rewriteColumnTitleInNamedFormulae(Spreadsheet $spreadsheet, string $oldTitle, string $newTitle): void
    {
        $pattern = $this->columnRetitlePattern !== ''
            ? $this->columnRetitlePattern
            : '/\[(@?)' . preg_quote($oldTitle, '/') . '\]/mui';

        foreach ($spreadsheet->getNamedFormulae() as $namedFormula) {
            $formula = $namedFormula->getValue();
            if (preg_match($pattern, $formula) === 1) {
                $formula = preg_replace($pattern, "[$1{$newTitle}]", $formula);
                $namedFormula->setValue($formula);
                ++$this->columnRetitleCount;
            }
        }
    }

    public function identifyFormulaValue(string $value): bool
    {
        $this->formulaCandidate = $value;
        $this->formulaIdentified = false;
        $this->formulaCandidateQuoted = false;
        $this->formulaCandidateNumeric = false;
        $this->formulaSegmentIndex = 0;

        if (substr($this->formulaCandidate, 0, 1) === '=') {
            $this->formulaCandidate = substr($this->formulaCandidate, 1);
        }

        if (is_numeric($this->formulaCandidate)) {
            $this->formulaCandidateNumeric = true;
            $this->formulaIdentified = true;

            return true;
        }

        return $this->scanFormulaSegments($this->formulaCandidate);
    }

    public function scanFormulaSegments(string $value): bool
    {
        $this->formulaCandidate = $value;
        $this->formulaCandidateQuoted = false;
        $this->formulaSegmentIndex = 0;
        $segMatcher = false;
        foreach (explode("'", $this->formulaCandidate) as $subVal) {
            ++$this->formulaSegmentIndex;
            $segMatcher = $segMatcher === false;
            $this->formulaCandidateQuoted = !$segMatcher;
            if (
                $segMatcher &&
                (preg_match('/[^_\p{N}\p{L}:, \$\'!]/miu', $subVal))
            ) {
                $this->formulaIdentified = true;

                return true;
            }
        }

        $this->formulaIdentified = false;

        return false;
    }
}

