private function getTableByName(Cell $cell): Table
{
    $worksheet = $cell->getWorksheet();
    $table = $worksheet->getTableByName($this->tableName);

    if ($table === null && $worksheet->getParent() !== null) {
        foreach ($worksheet->getParent()->getWorksheetIterator() as $sheet) {
            $table = $sheet->getTableByName($this->tableName);
            if ($table !== null) {
                break;
            }
        }
    }

    if ($table === null) {
        throw new Exception("Table {$this->tableName} for Structured Reference cannot be located");
    }

    return $table;
}

